import java.sql.*;
import javax.servlet.http.*;
import java.security.MessageDigest;

public class UserLogin extends HttpServlet {
    public void doPost(HttpServletRequest request, HttpServletResponse response) {
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/users", "root", "password");

            // Use PreparedStatement to prevent SQL injection
            // Parameterized queries separate SQL code from user data
            String query = "SELECT * FROM users WHERE username = ? AND password_hash = ?";
            PreparedStatement pstmt = conn.prepareStatement(query);

            // Set parameters safely - input is treated as data, not executable code
            pstmt.setString(1, username);
            pstmt.setString(2, hashPassword(password)); // Hash password before comparison

            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                // User authenticated securely
                response.getWriter().println("Login successful");
            } else {
                response.getWriter().println("Invalid credentials");
            }

            // Properly close resources
            rs.close();
            pstmt.close();
            conn.close();

        } catch (Exception e) {
            // Log error securely without exposing sensitive information
            System.err.println("Database error occurred during authentication");
        }
    }

    // Helper method to hash passwords securely
    private String hashPassword(String password) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashedBytes = md.digest(password.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashedBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
